function checkSecurity(result) {
    try {
        var url = result.url();
        var src = result.body();
        var code = result.code();

        var isBlocked = false;
        if (code === 202 || code === 403 || code === 503 || code === 429) {
            isBlocked = true;
        } else if (src && (
            src.indexOf("probe.js") !== -1 ||
            src.indexOf("x-waf-captcha") !== -1 ||
            src.indexOf("TCaptcha") !== -1 ||
            src.indexOf("turing.captcha") !== -1 ||
            src.indexOf("安全验证") !== -1 ||
            src.indexOf("请完成安全验证") !== -1 ||
            src.indexOf("Just a moment") !== -1
        )) {
            isBlocked = true;
        }

        if (!isBlocked) {
            source.put("waf_block_count", "0");
            return result;
        }

        java.log("检测到起点安全验证或WAF拦截: " + url);
        var count = parseInt(source.get("waf_block_count") || "0");
        count++;
        source.put("waf_block_count", count.toString());

        if (count <= 2) {
            java.log("尝试使用系统WebView自动执行环境验证...");
            try {
                var webResult = java.webView(url, url, 
                    "setTimeout(function() { window.legado.getHTML(document.documentElement.outerHTML); }, 4000);"
                );
                if (webResult && webResult.indexOf("probe.js") === -1 && webResult.indexOf("安全验证") === -1) {
                    java.log("WebView自动验证通过，重新连接");
                    source.put("waf_block_count", "0");
                    result = java.connect(url);
                    return result;
                }
            } catch (e) {
                java.log("WebView执行异常: " + e);
            }
        }

        java.log("唤起浏览器进行手动安全验证...");
        java.toast("检测到起点安全验证，请在弹出窗口中完成滑动验证");
        java.startBrowserAwait(url, "起点安全验证");
        source.put("waf_block_count", "0");
        result = java.connect(url);
        return result;
    } catch (err) {
        java.log("验证检查异常: " + err);
        return result;
    }
}

result = checkSecurity(result);
result;
